package dev.kelmagic.resonance;
import dev.kelmagic.*;import dev.kelmagic.research.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.nbt.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.*;import net.minecraft.resources.ResourceLocation;
/** Server-authoritative 9-slot vessel. One sample per slot, persisted ritual and consumption. */
public final class ResonanceEntity extends BlockEntity implements MenuProvider {
 public float spin,spinSpeed=.024f;public long particleTick=-1;private boolean loading;public int elapsed,total;public boolean paused;private UUID owner;private String research="";private boolean production;private ItemStack output=ItemStack.EMPTY;private int cursor;private final List<Integer> order=new ArrayList<>();public final List<ItemStack> echoes=new ArrayList<>(Collections.nCopies(9,ItemStack.EMPTY));
 public final SimpleContainer inventory=new SimpleContainer(9){public int getMaxStackSize(){return 64;}public void setChanged(){super.setChanged();if(!loading){ResonanceEntity.this.setChanged();sync();}}};
 public final ContainerData data=new ContainerData(){public int getCount(){return 3;}public int get(int i){return i==0?elapsed:i==1?total:paused?1:0;}public void set(int i,int v){if(i==0)elapsed=v;else if(i==1)total=v;else paused=v!=0;}};
 public ResonanceEntity(BlockPos p,BlockState s){super(MagicResonance.ENTITY.get(),p,s);}
 public boolean active(){return total>0;}public String research(){return research;}
 public void sync(){if(level!=null&&!level.isClientSide)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),3);}
 public static void tick(Level l,BlockPos pos,BlockState s,ResonanceEntity d){if(l.isClientSide){d.spinSpeed+=((d.active()&&!d.paused?.24f:.024f)-d.spinSpeed)*.07f;d.spin=(d.spin+d.spinSpeed)%(float)(Math.PI*2);}else d.advance();}
 public boolean matches(ResearchCatalog.Step st){if(!st.kind().equals("resonance")||java.util.stream.IntStream.range(0,9).anyMatch(i->inventory.getItem(i).getCount()>1))return false;if(st.result().equals("mana_potion")){return inventory.getItem(0).is(Items.GLASS_BOTTLE)&&inventory.getItem(1).is(MagicContent.MANA_CORE)&&inventory.getItem(2).is(Items.AMETHYST_SHARD)&&java.util.stream.IntStream.range(3,9).allMatch(i->inventory.getItem(i).isEmpty());}String id=st.result().substring(st.result().indexOf(':')+1);return !InfusionRecipes.matching(level,this,InfusionRecipes.researchFor(id)).isEmpty();}
 public boolean start(ServerPlayer p,String word){if(active()||!p.isAlive()||p.isSpectator()||p.distanceToSqr(net.minecraft.world.phys.Vec3.atCenterOf(worldPosition))>16||!Research.inventoryWords(p).contains(word)||!ResearchCatalog.learned(Research.state(p),"resonance_station"))return false;
 for(var n:ResearchCatalog.NODES){if(n.free()||n.sealed()||n.steps().isEmpty()||!Research.requiredWord(n).equals(word))continue;var st=n.steps().getLast();if(!st.kind().equals("resonance"))continue;boolean known=ResearchCatalog.learned(Research.state(p),n.id());boolean hypothesis=Research.hasPaper(p,n.id())&&Research.state(p).started().contains(n.id())&&Research.progress(Research.state(p),n)==n.steps().size()-1;if(!known&&!hypothesis)continue;if(!matches(st))continue;var result=n.id().equals("mana_potion")?net.minecraft.world.item.alchemy.PotionContents.createItemStack(Items.POTION,MagicContent.MANA):InfusionRecipes.matching(level,this,n.id());if(result.isEmpty())continue;production=known;output=known?result.copy():result.copyWithCount(1);owner=p.getUUID();research=n.id();elapsed=cursor=0;order.clear();for(int i=0;i<9;i++){echoes.set(i,inventory.getItem(i).copy());if(i>0&&!inventory.getItem(i).isEmpty())order.add(i);}if(order.isEmpty())return false;total=order.size()*100;paused=false;setChanged();sync();p.sendSystemMessage(Component.literal("Станция услышала отклик. Образцы уступают его центру.").withStyle(net.minecraft.ChatFormatting.DARK_AQUA));return true;}return false;}
 public void advance(){if(level instanceof ServerLevel l)advance(owner==null?null:l.getServer().getPlayerList().getPlayer(owner));}
 public void advance(ServerPlayer p){if(!active()||!(level instanceof ServerLevel l))return;var n=ResearchCatalog.BY_ID.get(research);boolean valid=p!=null&&owner!=null&&owner.equals(p.getUUID())&&p.isAlive()&&n!=null&&(production?ResearchCatalog.learned(Research.state(p),research):Research.hasPaper(p,research)&&!ResearchCatalog.learned(Research.state(p),research)&&Research.progress(Research.state(p),n)==n.steps().size()-1);if(!valid){if(!paused){paused=true;setChanged();sync();}return;}if(paused){paused=false;sync();}elapsed++;if(elapsed%10==0){l.playSound(null,worldPosition,net.minecraft.sounds.SoundEvents.AMETHYST_BLOCK_CHIME,net.minecraft.sounds.SoundSource.BLOCKS,.16f,1.1f+(float)Math.sin(elapsed*.08)*.25f);}
 if(elapsed%100==0&&cursor<order.size()){int slot=order.get(cursor++);var old=inventory.getItem(slot).copy();inventory.setItem(slot,ItemStack.EMPTY);}
 if(elapsed>=total){inventory.setItem(0,output.copy());if(!production){Research.save(p,Research.state(p).add("evidence",research+":"+(n.steps().size()-1)));Research.completePapers(p);Research.thought(p,n,n.steps().size()-1);}dev.kelmagic.server.MagicProgress.inventory(p);l.sendParticles(net.minecraft.core.particles.ParticleTypes.ENCHANT,worldPosition.getX()+.5,worldPosition.getY()+1.05,worldPosition.getZ()+.5,32,.2,.15,.2,.15);l.playSound(null,worldPosition,net.minecraft.sounds.SoundEvents.ENCHANTMENT_TABLE_USE,net.minecraft.sounds.SoundSource.BLOCKS,.65f,1.3f);elapsed=total=cursor=0;order.clear();owner=null;research="";output=ItemStack.EMPTY;production=false;for(int i=0;i<9;i++)echoes.set(i,ItemStack.EMPTY);sync();}else if(elapsed%10==0)sync();setChanged();}
 protected void saveAdditional(CompoundTag t,HolderLookup.Provider r){super.saveAdditional(t,r);write(t,r);}
 private void write(CompoundTag t,HolderLookup.Provider r){var list=new ListTag();for(int i=0;i<9;i++){var v=new CompoundTag();v.putInt("Slot",i);if(!inventory.getItem(i).isEmpty())v.put("Stack",inventory.getItem(i).save(r));if(!echoes.get(i).isEmpty())v.put("Echo",echoes.get(i).save(r));list.add(v);}t.put("Items",list);t.putBoolean("Production",production);if(!output.isEmpty())t.put("Output",output.save(r));t.putInt("Elapsed",elapsed);t.putInt("Total",total);t.putBoolean("Paused",paused);t.putInt("Cursor",cursor);t.putString("Research",research);if(owner!=null)t.putUUID("Owner",owner);t.putIntArray("Order",order);}
 protected void loadAdditional(CompoundTag t,HolderLookup.Provider r){super.loadAdditional(t,r);loading=true;try{inventory.clearContent();for(int i=0;i<9;i++)echoes.set(i,ItemStack.EMPTY);var list=t.getList("Items",Tag.TAG_COMPOUND);for(int j=0;j<list.size();j++){var v=list.getCompound(j);int i=v.getInt("Slot");if(i>=0&&i<9){inventory.setItem(i,ItemStack.parseOptional(r,v.getCompound("Stack")));echoes.set(i,ItemStack.parseOptional(r,v.getCompound("Echo")));}}elapsed=Math.clamp(t.getInt("Elapsed"),0,800);total=Math.clamp(t.getInt("Total"),0,800);cursor=Math.clamp(t.getInt("Cursor"),0,8);paused=t.getBoolean("Paused");research=t.getString("Research");production=t.getBoolean("Production");output=ItemStack.parseOptional(r,t.getCompound("Output"));owner=t.hasUUID("Owner")?t.getUUID("Owner"):null;order.clear();for(int i:t.getIntArray("Order"))if(i>0&&i<9&&!order.contains(i))order.add(i);}finally{loading=false;}}
 public CompoundTag getUpdateTag(HolderLookup.Provider r){var t=new CompoundTag();write(t,r);return t;}public net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket getUpdatePacket(){return net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket.create(this);}
 public Component getDisplayName(){return Component.translatable("block.kelmagic.resonance_station");}public AbstractContainerMenu createMenu(int id,Inventory inv,Player p){return new ResonanceMenu(id,inv,this);}
 public static boolean spoken(ServerPlayer p,String word){var candidates=new ArrayList<ResonanceEntity>();for(var pos:BlockPos.betweenClosed(p.blockPosition().offset(-4,-2,-4),p.blockPosition().offset(4,2,4)))if(p.serverLevel().hasChunkAt(pos)&&p.serverLevel().getBlockEntity(pos) instanceof ResonanceEntity d&&p.distanceToSqr(net.minecraft.world.phys.Vec3.atCenterOf(pos))<=16)candidates.add(d);candidates.sort(Comparator.comparingDouble(d->p.distanceToSqr(net.minecraft.world.phys.Vec3.atCenterOf(d.getBlockPos()))));for(var d:candidates)if(d.start(p,word))return true;return false;}
}
